import{_ as o,l as n,o as e,c as i,v as t,p as l,x as r,d,i as E,S as A}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"HBM 与 3D 堆叠","description":"","frontmatter":{"title":"HBM 与 3D 堆叠","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hbm-3d-stack.md","filePath":"cs/hbm-3d-stack.md","lastUpdated":1789023840000}'),B={name:"cs/hbm-3d-stack.md"};function h(c,a,p,D,M,m){const s=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="hbm-与-3d-堆叠" tabindex="-1">HBM 与 3D 堆叠 <a class="header-anchor" href="#hbm-与-3d-堆叠" aria-label="Permalink to &quot;HBM 与 3D 堆叠&quot;">​</a></h1><div class="epigraph"><p>把 DRAM 晶片叠在逻辑基片上，用硅通孔做很宽很短的通道：带宽上来，容量与热仍受堆叠层数限制。</p><footer>—— 据 JEDEC HBM 标准；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/fr-fcfs">上一课</a>的调度在离芯片 DIMM 通道上跑，引脚数限制宽度。缺口是 <strong>HBM</strong>：3D 堆叠 DRAM + 宽 I/O，组织仍是通道/伪通道/bank/行，物理从 PCB 金手指换成中介层与 TSV。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DDR DIMM：板级走线、几十比特宽、GHz 级。HBM：每堆叠多个伪通道，数据宽度一个数量级以上，时钟可以更保守，靠并行取带宽。缺口不是新的行缓冲定义，而是<strong>封装层次</strong>改变通道数量与功耗分布：PHY 在中介层旁，控制器仍做 ACT/RD 与刷新。</p><p>3D 堆叠：TSV 连多层 DRAM 晶片。热从逻辑芯片和 DRAM 自刷新一起来，功耗墙在垂直方向更紧。</p><h3 id="hbm-不是「把-cache-做进-dram-工艺」" tabindex="-1">HBM 不是「把 cache 做进 DRAM 工艺」 <a class="header-anchor" href="#hbm-不是「把-cache-做进-dram-工艺」" aria-label="Permalink to &quot;HBM 不是「把 cache 做进 DRAM 工艺」&quot;">​</a></h3><p>HBM 仍是 DRAM 电容，要刷新、有行缓冲。逻辑基片可以含控制器，不把 HBM 变成 SRAM 缓存。把 HBM 当片上 SRAM，一致性与保留时间会说错。也不等于 NAND 闪存堆叠（后课）。</p><p><span class="marginnote">JEDEC HBM/HBM2/HBM3 规范定义接口。CA:AQA 用 3D 与宽 I/O 讲带宽。本课不写 TSV 光刻工艺，不把 GPU 型号当标准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>地址映射切到更多伪通道。调度器实例变多，每伪通道仍可 FR-FCFS。容量：层数 × 密度，不及多 DIMM 服务器容量时用 DDR 做远端、HBM 做近端（异构内存），OS 可见性后课 NVM 再对照。</p>',11)),(e(),l(A,null,{default:r(()=>[E(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOGIC%5B%22%E9%80%BB%E8%BE%91%E8%8A%AF%E7%89%87%20%2F%20%E5%9F%BA%E7%89%87%22%5D%20--%3E%20INTP%5B%22%E4%B8%AD%E4%BB%8B%E5%B1%82%22%5D%0A%20%20INTP%20--%3E%20STK%5B%22DRAM%20%E6%99%B6%E7%89%87%E5%A0%86%E5%8F%A0%20TSV%22%5D%0A%20%20STK%20--%3E%20PC%5B%22%E4%BC%AA%E9%80%9A%E9%81%93%20%2B%20%E8%A1%8C%E7%BC%93%E5%86%B2%22%5D%0A%20%20PC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9D%9E%E6%98%93%E5%A4%B1%E4%B8%8E%E5%8F%A6%E4%B8%80%E5%A5%97%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>训练与校准仍在，只是通道极多，PHY 数字控制更重。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>软错误：堆叠与 TSV 不取消 ECC。老化：热点在中心层。经济学：中介层与堆叠良率提高 NRE，故出现在带宽关键的加速器，而不是每块 PC 主板。后课闪存是另一介质，不要把「堆叠」三字共用成同一课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲混合键合的全部工艺选项，不进入光刻套准。不把 HBM 带宽写成大模型必修——系统栏只给接口。不讨论显卡零售。</p><p>后课默认：HBM 是宽而短的 DRAM 通道加 3D 堆叠；命令语义仍是 DRAM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宽伪通道 + TSV 堆叠拉带宽；仍是 DRAM 行缓冲与刷新。</li><li>热与良率限制层数与谁用得起。</li><li>下一课介质换成非易失。</li><li>出处：JEDEC HBM；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const C=o(B,[["render",h]]);export{T as __pageData,C as default};
